   await begin(p);await p.keyboard.down('ArrowLeft');await p.keyboard.down('ArrowLeft');await p.wait_for_timeout(120);s=await snap(p);assert s['lane']==0 and s['stats']['laneChanges']==1;await p.keyboard.up('ArrowLeft');await p.keyboard.press('ArrowLeft');assert (await snap(p))['stats']['laneChanges']==1;await p.keyboard.press('ArrowRight');await p.keyboard.press('ArrowRight');await p.keyboard.press('ArrowRight');assert (await snap(p))['lane']==2;checks.append('Real held/repeated direction changes one lane; repeated boundary input never leaves three lanes')
