   await p.keyboard.press('r');await begin(p);await complete(p,stop=lambda s:s['cargo']>=1);await p.keyboard.press('ArrowUp');await p.keyboard.press('p');before=await snap(p);await load(p,args.url,True);after=await snap(p);assert after['state']=='paused' and all(before[k]==after[k] for k in FIELDS);assert after['accumulator']==0 and after['gesture'] is None;await p.wait_for_timeout(650);assert (await snap(p))['ticks']==after['ticks'];report['restore']={k:after[k] for k in FIELDS};await p.locator('#resume').click();end,actions,elapsed=await complete(p);assert end['state']=='won' and end['hp']==3;report['restoreAndWin']={'state':end['state'],'cargo':end['cargo'],'hp':end['hp'],'score':end['score'],'stats':end['stats'],'actualLog':end['log']};checks.append('Refresh exactly replays a mid-jump route paused, then real keyboard input finishes with full health')
