   await p.keyboard.press('r');s=await snap(p);assert s['hp']==3 and s['ticks']==0 and s['cargo']==0 and s['best']['1']==best;await p.set_viewport_size({'width':1440,'height':1200});await begin(p);end=await until(p,lambda s:s['state']=='lost');assert end['stats']['hits']==3 and end['hp']==0 and end['stats']['settlements']==1 and end['best']['1']==best;report['naturalFailure']={'ticks':end['ticks'],'hp':end['hp'],'cargo':end['cargo'],'stats':end['stats'],'actualLog':end['log']};await p.locator('#primary-action').click();assert (await snap(p))['state']=='ready';checks.append('Unattended natural collisions fail on the third distinct row and retry restores normal resources without erasing best')
